mapper.select:
select t_b_api_plugin.id as api_plugin_id, t_b_api_plugin.plugin_id as api_plugin_plugin_id, t_b_api_plugin.name as api_plugin_name, t_b_api_plugin.description as api_plugin_description, t_b_api_plugin.enable as api_plugin_enable, t_b_api_plugin.default_price as api_plugin_default_price, t_b_api_plugin.default_rate_limit as api_plugin_default_rate_limit, t_b_api_plugin.default_access_mode as api_plugin_default_access_mode, t_b_api_plugin.source as api_plugin_source, t_b_api_plugin.version_name as api_plugin_version_name, t_b_api_plugin.version_code as api_plugin_version_code, t_b_api_plugin.file_hash as api_plugin_file_hash, t_b_api_plugin.jar_name as api_plugin_jar_name, t_b_api_plugin.signer_key_id as api_plugin_signer_key_id, t_b_api_plugin.openapi as api_plugin_openapi, t_b_api_plugin.config_schema as api_plugin_config_schema, t_b_api_plugin.load_error as api_plugin_load_error, t_b_api_plugin.create_time as api_plugin_create_time, t_b_api_plugin.update_time as api_plugin_update_time, t_b_api_plugin.version as api_plugin_version from t_b_api_plugin
t_b_api_plugin.enable = 1
and lower(t_b_api_plugin.name) like concat('%', lower(#{searchName}), '%')
and exists (select 1 from t_b_api_interface as tbai where tbai.plugin_id = t_b_api_plugin.plugin_id and tbai.enable = 1
and (coalesce(tbai.access_mode, t_b_api_plugin.default_access_mode, 'RESTRICTED') = 'DEFAULT'
#{item}
)
)
order by t_b_api_plugin.create_time desc, t_b_api_plugin.plugin_id desc
